public class Hand {
  public static void main(String[] a) throws Exception {
    URLClassLoader cl=new URLClassLoader(new URL[]{new java.io.File("/tmp/build/verify-DSExp05_Hash").toURI().toURL()},null);
    Class<?> C=cl.loadClass("Main");
    Method av=C.getDeclaredMethod("addVirtualNode",String.class); av.setAccessible(true);
    Method gs=C.getDeclaredMethod("getServer",String.class); gs.setAccessible(true);
    Method gh=C.getDeclaredMethod("getHash",String.class); gh.setAccessible(true);
    Field vn=C.getDeclaredField("virtualNodes"); vn.setAccessible(true);
    String[] ips={"192.168.0.1","10.0.0.7","172.16.5.9"};
    for(String ip:ips) av.invoke(null,ip);
    TreeMap<Integer,String> ring=(TreeMap<Integer,String>)vn.get(null);
    System.out.println("ring size="+ring.size()+" (expect 30 = 3 servers x 10 VNs)");
    // independent hand implementation of clockwise successor
    Integer[] ks=ring.keySet().toArray(new Integer[0]);
    int ok=0,bad=0,npe=0;
    for(int i=0;i<3000;i++){
      String k="client"+i; int h=(Integer)gh.invoke(null,k);
      String expect=null;
      for(Integer key:ks) if(key>=h){ String v=ring.get(key); expect=v.substring(0,v.indexOf("##")); break; }
      String got; try{ got=(String)gs.invoke(null,k);}catch(InvocationTargetException e){ got="EX:"+e.getCause().getClass().getSimpleName(); npe++; }
      String want = (expect==null)? "EX:NullPointerException" : expect;   // no wrap-around in reference
      if(want.equals(got)) ok++; else { bad++; if(bad<5) System.out.println("BAD "+k+" h="+h+" want="+want+" got="+got); }
    }
    System.out.println("hand-checked routes ok="+ok+" bad="+bad+" (above-max-key NPE cases="+npe+")");
    Map<String,Integer> dist=new TreeMap<>();
    for(int i=0;i<3000;i++){ try{ dist.merge((String)gs.invoke(null,"client"+i),1,Integer::sum);}catch(Exception e){} }
    System.out.println("distribution across servers: "+dist);
    System.out.println("first 4 ring entries: ");
    int c=0; for(Map.Entry<Integer,String> e:ring.entrySet()){ System.out.println("  "+e.getKey()+" -> "+e.getValue()); if(++c==4)break; }
  }
}
